import com.vaadin.flow.testbench.unit.SpringBrowserlessTest;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
public class ItemsViewTest extends SpringBrowserlessTest {
    @Test
    public void testViewLoads() {
        navigate(ItemsView.class);

        H1 heading = $(H1.class).first();
        assertNotNull(heading);
        assertEquals("Items", heading.getText());
    }

    @Test
    public void testAddItem() {
        navigate(ItemsView.class);

        TextField itemField = $(TextField.class).first();
        Button addButton = $(Button.class).first();
        Span itemCount = $(Span.class).first();

        itemField.setValue("First Item");
        addButton.click();

        assertEquals("Items: 1", itemCount.getText());
        assertEquals("", itemField.getValue());
    }

    @Test
    public void testAddBlankItemMarksInvalid() {
        navigate(ItemsView.class);

        TextField itemField = $(TextField.class).first();
        Button addButton = $(Button.class).first();

        itemField.setValue("");
        addButton.click();

        assertTrue(itemField.isInvalid());
    }

    @Test
    public void testClearItems() {
        navigate(ItemsView.class);

        TextField itemField = $(TextField.class).first();
        Button addButton = $(Button.class).first();
        Button clearButton = $(Button.class).last();
        Span itemCount = $(Span.class).first();

        itemField.setValue("Item 1");
        addButton.click();
        itemField.setValue("Item 2");
        addButton.click();

        assertEquals("Items: 2", itemCount.getText());

        clearButton.click();

        assertEquals("Items: 0", itemCount.getText());
    }
}
